-- Data, not schema: the founders' LinkedIn profiles and portraits (the same ones
-- the website shows, 400 px JPEG). Matched by slug; a missing card is a no-op.
UPDATE "Member" SET "linkedinUrl" = 'https://www.linkedin.com/in/vandl',
  "photo" = decode('', 'base64'),
  "photoType" = 'image/jpeg', "photoUpdatedAt" = CURRENT_TIMESTAMP
WHERE "slug" = 'vandl';

UPDATE "Member" SET "linkedinUrl" = 'https://www.linkedin.com/in/jan-rychl%C3%ADk-3961891a5/',
  "photo" = decode('', 'base64'),
  "photoType" = 'image/jpeg', "photoUpdatedAt" = CURRENT_TIMESTAMP
WHERE "slug" = 'rychlik';
